js:(async () => { const H = { Authorization: 'Bearer ' + localStorage.getItem('erp_token'), 'Content-Type': 'application/json' }; const J = async (m, u, b) => { const r = await fetch('/api' + u, { method: m, headers: H, body: b ? JSON.stringify(b) : undefined }); return r.status === 204 ? null : r.json() };
const taken = new Set((await J('GET', '/quality-types/item-settings')).filter((x) => x.typeCode).map((x) => x.itemId));
const it = (await J('GET', '/items')).filter((x) => x.active !== false && !taken.has(x.id))[0];
const a = await J('POST', '/quality-check-items', { format: 'CODE', name: 'QA재고2-흐름외관', required: true });
const d = await J('POST', '/quality-check-items/' + a.id + '/details', { name: 'QA상' });
const b = await J('POST', '/quality-check-items', { format: 'TEXT', name: 'QA재고2-흐름비고', required: true });
const t = await J('POST', '/quality-types', { code: 'QAFLOWQI', name: 'QA재고2-흐름검사입력' });
await J('PUT', '/quality-types/' + t.id + '/slots', { slots: [{ checkItemId: b.id, slot: 1 }, { checkItemId: a.id, slot: 1 }] });
await J('POST', '/quality-types/' + t.id + '/items', { itemIds: [it.id] });
const q = await J('POST', '/quality-inspections', { remark: 'QA재고2', lines: [{ itemId: it.id, method: 'FULL', quantity: 1 }] });
sessionStorage.setItem('qic', JSON.stringify({ item: it.id, name: it.name, a: a.id, b: b.id, t: t.id, q: q.id, no: q.inspectionNo }));
return q.inspectionNo })()
